mapper.insert:
INSERT INTO assistant_conversation (
    conversation_uid, user_id, project_id, title, summary, pinned, created_at, updated_at
)
VALUES (
    #{conversationUid}, #{userId}, #{projectId}, #{title}, #{summary}, #{pinned}, NOW(), NOW()
