mapper.update:
UPDATE assistant_conversation
SET archived_at = #{archivedAt},
    updated_at = NOW()
WHERE conversation_uid = #{conversationUid}
  AND user_id = #{userId}
  AND deleted_at IS NULL

UPDATE assistant_conversation
